 * @layout testimonial
 * @summary Quote or testimonial display with attribution and optional imagery.
 * @remarks
 * ✅ Use Testimonial when:
 * - Displaying customer or user testimonials and quotes
 * - You want to highlight a statement with visual emphasis
 * - Attribution and context (name, title, image) are important
 * 🚫 Don't use Testimonial when:
 * - Displaying inline quotes in body text — use a blockquote element instead
 * - The statement is the main focus — use Hero or Card instead
 * @accessibility
 * - Use `<blockquote>` semantically for the quote
 * - Ensure attribution is clear and associated with the quote
 * - If using images, provide alt text
 * @selector div[class~="pfx-testimonial"]
 * @part .container - Root container for the testimonial.
 * @part .quote - The quoted text.
 * @part .author - Attribution author name.
 * @part .title - Optional author title or affiliation.
 * @part .avatar - Optional author profile image.
 * @related card
 */

div[class~="pfx-testimonial"] {
  display: flex;
  gap: var(--instui-space-medium);
  padding: var(--instui-space-large);
  border-left: 4px solid var(--instui-color-primary);
  background-color: var(--instui-color-surface);
  border-radius: var(--instui-radius-medium);
}

div[class~="pfx-testimonial"] .pfx-avatar {
