 * @layout callout
 * @summary Inline information alert for a short reminder or note.
 * @remarks
 * ✅ Use Callout when:
 * - You need to highlight important information or reminders inline
 * - The message is relatively brief (a sentence to a short paragraph)
 * - The alert should draw attention without interrupting the main flow
 * 🚫 Don't use Callout when:
 * - The message requires interaction or multiple actions — use a Modal or Alert Dialog
 * - The content is the main focus of the page — use a Card or Hero layout instead
 * @accessibility
 * - Ensure the alert role is properly applied (role="alert" or role="status")
 * - Use semantic color contrast that meets WCAG AA standards
 * - Don't rely on color alone to convey meaning
 * @selector div[class~="pfx-callout"]
 * @part .wrapper - Root container for the alert.
 * @part .icon - Optional icon to the left of the content.
 * @part .content - Container for the text content.
 * @slot message - Alert message content
 * @related alert
 */

div[class~="pfx-callout"] {
  display: flex;
  gap: var(--instui-space-small);
  padding: var(--instui-space-medium);
  border-radius: var(--instui-radius-medium);
  background-color: var(--instui-color-info-background);
  border: 1px solid var(--instui-color-info-border);
  color: var(--instui-color-info-text);
}

div[class~="pfx-callout"] .pfx-icon {
  flex-shrink: 0;
  width: var(--instui-size-small);
  height: var(--instui-size-small);
}

div[class~="pfx-callout"] .pfx-content {
  flex: 1;
  min-width: 0;
}

/* i18n placeholder for slot content extraction */
:slot(message)::before {
  content: "Alert message";
