 * @part .pfx-avatar - Optional author profile image.
 * @part .pfx-content - Container for quote and attribution.
 * @part .pfx-quote - The quoted text.
 * @part .pfx-author - Attribution author name.
 * @part .pfx-title - Optional author title or affiliation.
 * @related card
 */
div[class~="pfx-testimonial"] {
  display: flex;
  gap: var(--instui-space-medium);
  padding: var(--instui-space-large);
  border-left: 4px solid var(--instui-color-primary);
  background-color: var(--instui-color-surface);
  border-radius: var(--instui-radius-medium);
}

div[class~="pfx-testimonial"] .pfx-avatar:optional {
  flex-shrink: 0;
  width: 60px;
  height: 60px;
  border-radius: 50%;
