  flex: 1;
}

div[class~="pfx-testimonial"] .pfx-content .pfx-quote {
  font-style: italic;
  color: var(--instui-color-text-primary);
  margin: 0 0 var(--instui-space-small) 0;
}

div[class~="pfx-testimonial"] .pfx-content .pfx-author {
  font-weight: var(--instui-font-weight-semibold);
  margin: 0;
}

div[class~="pfx-testimonial"] .pfx-content .pfx-title:optional {
  font-size: var(--instui-font-size-small);
  color: var(--instui-color-text-secondary);
  margin: 0;
}
"}

